16	  const editingTask = tasks.find((task) => task.id === editingId) ?? null;
17	
18	  const updateTask = (updated: Task) => {
19	    setTasks((current) => current.map((task) => (task.id === updated.id ? updated : task)));
20	    setEditingId(null);
