{"path": "src/components/ResponsiveNav.tsx", "mode": "create", "content": "import { useEffect, useState } from 'react';

const links = [
  { href: '#board', label: 'Board' },
  { href: '#activity', label: 'Activity' },
  { href: '#reports', label: 'Reports' },
];

function currentHash() {
  return typeof window === 'undefined' ? '' : window.location.hash;
}

export function ResponsiveNav() {
  const [open, setOpen] = useState(false);
  const [hash, setHash] = useState(currentHash);

  useEffect(() => {
    const syncHash = () => setHash(currentHash());
    window.addEventListener('hashchange', syncHash);
    return () => window.removeEventListener('hashchange', syncHash);
  }, []);

  return (
    <nav className="top-nav" aria-label="Primary navigation">
      <a className="brand" href="#top">RB</a>
      <button
        className="menu-button"
        type="button"
        aria-expanded={open}
        aria-controls="nav-links"
        onClick={() => setOpen((value) => !value)}
      >
        Menu
      </button>
      <div id="nav-links" className={`nav-links ${open ? 'open' : ''}`}>
        {links.map((link) => (
          <a
            key={link.href}
            href={link.href}
            aria-current={hash === link.href ? 'page' : undefined}
            onClick={() => {
              setHash(link.href);
              setOpen(false);
            }}
          >
            {link.label}
          </a>
        ))}
      </div>
    </nav>
  );
}
"}

